#!/usr/bin/env node
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { formatOklch, contrastRatio, serialisedComponents, needsP3Fallback, formatDisplayP3, oklchToHex } from './lib/color.mjs';
import { INFIMA_VERSION, INFIMA_COLOR_VARS, INFIMA_EXCUSED, INFIMA_MAP, INFIMA_NON_COLOUR } from './lib/infima-map.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const tokens = JSON.parse(readFileSync(join(root, 'tokens.json'), 'utf8'));
const MODES_KEY = 'broker.package.modes';
const HEADER = '/* Generated by scripts/build-tokens.mjs from tokens.json. Edit tokens.json, then rebuild. */\n';
const CONSTRAINT = /\b(never|must|exempt|only|3:1|4\.5:1)\b/i;

function* leaves(node, path = [], type) {
  for (const [k, v] of Object.entries(node)) {
    if (k.startsWith('$')) continue;
    const t = v.$type ?? type;
    if (v.$value !== undefined) yield { path: [...path, k], type: t, token: v };
    else yield* leaves(v, [...path, k], t);
  }
}

const varName = (path) => `--pb-${path.join('-')}`;
const dim = (d) => `${d.value}${d.unit}`;
const refPath = (ref) => ref.replace(/[{}]/g, '').split('.');
const alias = (ref) => `var(${varName(refPath(ref))})`;
const isRef = (v) => typeof v === 'string' && /^\{[^{}]+\}$/.test(v);

function css(type, value, token) {
  if (isRef(value)) return alias(value);
  switch (type) {
    case 'color': {
      // Emit edge colours as sRGB here; implicit P3 fallbacks can escape their
      // print/theme scope during downstream media-query optimization.
      if (!needsP3Fallback(value)) return formatOklch(value.components, value.alpha);
      const alpha = value.alpha === undefined || value.alpha === 1 ? '' : Math.round(value.alpha * 255).toString(16).padStart(2, '0');
      return oklchToHex(serialisedComponents(value.components)) + alpha;
    }
    case 'dimension':
      return dim(value);
    case 'duration':
      return `${value.value}${value.unit}`;
    case 'fontFamily':
      return value.map((f) => (/\s/.test(f) ? `"${f}"` : f)).join(', ');
    case 'cubicBezier':
      return `cubic-bezier(${value.join(', ')})`;
    case 'shadow':
      return `${dim(value.offsetX)} ${dim(value.offsetY)} ${dim(value.blur)} ${dim(value.spread)} ${isRef(value.color) ? alias(value.color) : formatOklch(value.color.components, value.color.alpha)}`;
    case 'number':
      return `${value}${token?.$extensions?.['broker.package.cssUnit'] ?? ''}`;
    case 'fontWeight':
      return String(value);
    default:
      throw new Error(`unsupported token type "${type}" (supported: color, dimension, duration, fontFamily, cubicBezier, shadow, number, fontWeight)`);
  }
}

const all = [...leaves(tokens)];

function validate() {
  const errors = [];
  const byName = new Map();
  const byPath = new Map(all.map((l) => [l.path.join('.'), l]));
  for (const l of all) {
    if (!l.type) errors.push(`${l.path.join('.')}: no $type and no inherited $type`);
    const name = varName(l.path);
    if (byName.has(name)) errors.push(`${l.path.join('.')} and ${byName.get(name)} flatten to the same name ${name}`);
    byName.set(name, l.path.join('.'));
    const refs = [];
    if (isRef(l.token.$value)) refs.push(l.token.$value);
    if (l.type === 'shadow' && isRef(l.token.$value.color)) refs.push(l.token.$value.color);
    for (const r of refs) {
      const target = refPath(r).join('.');
      if (!byPath.has(target)) errors.push(`${l.path.join('.')}: reference ${r} does not exist`);
      if (target === l.path.join('.')) errors.push(`${l.path.join('.')}: reference to itself`);
    }
  }
  if (errors.length) {
    console.error(errors.join('\n'));
    process.exit(1);
  }
}
validate();

const note = (token) => (token.$description && CONSTRAINT.test(token.$description) ? ` /* ${token.$description} */` : '');
const decl = ({ path, type, token }, value = token.$value, withComment = true, indent = '  ') =>
  `${indent}${varName(path)}: ${css(type, value, token)};${withComment ? note(token) : ''}`;
const modal = all.filter((l) => l.token.$extensions?.[MODES_KEY]);
const composite = all.filter((l) => l.type === 'shadow');
const fixed = all.filter((l) => !l.token.$extensions?.[MODES_KEY] && l.type !== 'shadow');
const lightBlock = (indent) => [...modal.map((l) => decl(l, l.token.$value, true, indent)), ...composite.map((l) => decl(l, l.token.$value, false, indent))].join('\n');
const darkBlock = (indent) => [...modal.map((l) => decl(l, l.token.$extensions[MODES_KEY].dark, false, indent)), ...composite.map((l) => decl(l, l.token.$value, false, indent))].join('\n');
const zeroed = fixed.filter((l) => l.type === 'duration' && l.token.$value.value > 0 && !l.token.$extensions?.['broker.package.loop']);

const p3Colors = modal.filter((l) => l.type === 'color' &&
  [l.token.$value, l.token.$extensions[MODES_KEY].dark].some(needsP3Fallback));
const p3Block = (mode, indent) => p3Colors.map((l) =>
  `${indent}${varName(l.path)}: ${formatDisplayP3(mode === 'light' ? l.token.$value : l.token.$extensions[MODES_KEY].dark)};`).join('\n');
// Both themes override the union of edge colours: a light fallback must never
// win just because the corresponding dark value is wholly inside sRGB.
const p3Css = p3Colors.length ?
  '\n/* Explicit P3 fallbacks keep every enhancement inside its theme scope. */\n' +
  '@supports (color: color(display-p3 0 0 0)) {\n' +
  '  @media (color-gamut: p3) {\n    :root,\n    [data-theme="light"] {\n' +
  p3Block('light', '      ') + '\n    }\n\n' +
  '    [data-theme="dark"] {\n' + p3Block('dark', '      ') + '\n    }\n  }\n\n' +
  // Keep media conditions together: optimizers can lift nested media rules.
  '  @media (prefers-color-scheme: dark) and (color-gamut: p3) {\n    :root:not([data-theme="light"], [data-theme="dark"]) {\n' +
  p3Block('dark', '      ') + '\n    }\n  }\n\n' +
  '  @media print and (color-gamut: p3) {\n    :root,\n    [data-theme] {\n' +
  p3Block('light', '      ') + '\n    }\n  }\n}\n' : '';

const tokensCss =
  HEADER +
  ':root {\n' +
  fixed.map((l) => decl(l)).join('\n') +
  '\n}\n\n' +
  ':root,\n[data-theme="light"] {\n  color-scheme: light;\n' +
  lightBlock('  ') +
  '\n}\n\n' +
  '/* auto: no data-theme, or data-theme="auto", follows the OS. */\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme="light"], [data-theme="dark"]) {\n    color-scheme: dark;\n' +
  darkBlock('    ') +
  '\n  }\n}\n\n' +
  '[data-theme="dark"] {\n  color-scheme: dark;\n' +
  darkBlock('  ') +
  '\n}\n\n' +
  '/* Print is always light, whatever the screen theme. */\n' +
  '@media print {\n  :root,\n  [data-theme] {\n    color-scheme: light;\n' +
  lightBlock('    ') +
  '\n  }\n}\n\n' +
  '@media (prefers-reduced-motion: reduce) {\n  :root {\n' +
  zeroed.map((l) => `    ${varName(l.path)}: 0ms;`).join('\n') +
  '\n  }\n}\n' + p3Css;

const TW_COLOR_ALIAS = { bg: 'canvas', text: 'fg', 'text-muted': 'muted', 'text-disabled': 'disabled', border: 'line', 'border-control': 'control' };
const twColor = (path) => {
  const n = path.slice(1).join('-');
  return TW_COLOR_ALIAS[n] ?? n;
};
const twKey = (n) => n.replace('-', '_');
const tw = [];
const twMap = (prefix, filter, name) => all.filter(filter).forEach((l) => tw.push(`  --${prefix}-${name(l.path)}: var(${varName(l.path)});`));
tw.push('  --color-*: initial;', '  --font-*: initial;', '  --text-*: initial;', '  --font-weight-*: initial;', '  --leading-*: initial;', '  --tracking-*: initial;', '  --radius-*: initial;', '  --shadow-*: initial;', '  --inset-shadow-*: initial;', '  --drop-shadow-*: initial;', '  --blur-*: initial;', '  --ease-*: initial;', '  --animate-*: initial;', '  --spacing-*: initial;', '  --container-*: initial;');
twMap('color', (l) => l.type === 'color', twColor);
twMap('font', (l) => l.path[0] === 'font' && l.path[1] === 'family', (p) => p[2]);
all.filter((l) => l.path[0] === 'font' && l.path[1] === 'size').forEach((l) => tw.push(`  --text-${l.path[2]}: var(${varName(l.path)});`));
twMap('font-weight', (l) => l.path[0] === 'font' && l.path[1] === 'weight', (p) => p[2]);
twMap('leading', (l) => l.path[0] === 'font' && l.path[1] === 'line-height', (p) => p[2]);
twMap('tracking', (l) => l.path[0] === 'font' && l.path[1] === 'letter-spacing', (p) => p[2]);
twMap('radius', (l) => l.path[0] === 'radius', (p) => p[1]);
twMap('shadow', (l) => l.path[0] === 'shadow', (p) => p[1]);
twMap('ease', (l) => l.path[0] === 'easing', (p) => p[1]);
twMap('spacing', (l) => l.path[0] === 'space', (p) => twKey(p[1]));
tw.push(`  --container-content: var(${varName(['size', 'content-max'])});`, `  --container-measure: var(${varName(['size', 'prose-max'])});`);
const breakpoints = all.filter((l) => l.path[0] === 'breakpoint').map((l) => `  --breakpoint-${l.path[1]}: ${css(l.type, l.token.$value, l.token)};`);
const tailwindCss =
  HEADER +
  '/* Breakpoints are literal because Tailwind compiles them into media queries, where var() does not resolve. */\n' +
  '/* No --spacing base: numeric utilities outside the scale (p-7) generate nothing. Fractions use an underscore (p-0_5, p-1_5). */\n' +
  '@theme inline {\n' + tw.join('\n') + '\n}\n\n' +
  '@theme {\n  --breakpoint-*: initial;\n' + breakpoints.join('\n') + '\n}\n\n' +
  '/* dark: matches an explicit dark scope, or the OS dark preference when no explicit light scope is nearer. */\n' +
  '@custom-variant dark {\n' +
  '  &:where([data-theme="dark"], [data-theme="dark"] *) {\n    @slot;\n  }\n' +
  '  @media (prefers-color-scheme: dark) {\n' +
  '    &:where(:root:not([data-theme="light"], [data-theme="dark"]), :root:not([data-theme="light"], [data-theme="dark"]) *):not(:where([data-theme="light"], [data-theme="light"] *)) {\n      @slot;\n    }\n  }\n}\n';

const colorVar = (name) => `var(--pb-${name})`;
const missingInfima = [];
const infimaLines = [];
for (const [k, v] of Object.entries(INFIMA_MAP)) {
  const target = v;
  const found = all.some((l) => varName(l.path) === `--pb-${target}`);
  if (!found) missingInfima.push(`${k} -> ${target}`);
  infimaLines.push(`  --ifm-${k}: ${colorVar(target)};`);
}
const unmappedColours = INFIMA_COLOR_VARS.filter((n) => !(n in INFIMA_MAP) && !(n in INFIMA_EXCUSED));
const unknownMapped = Object.keys(INFIMA_MAP).filter((n) => !INFIMA_COLOR_VARS.includes(n) && !INFIMA_NON_COLOUR.has(n));
if (missingInfima.length || unmappedColours.length || unknownMapped.length) {
  console.error(`Infima mapping incomplete (infima ${INFIMA_VERSION}):`);
  if (missingInfima.length) console.error(`  targets that are not tokens: ${missingInfima.join(', ')}`);
  if (unmappedColours.length) console.error(`  colour variables neither mapped nor excused: ${unmappedColours.join(', ')}`);
  if (unknownMapped.length) console.error(`  mapped variables not in the pinned Infima list: ${unknownMapped.join(', ')}`);
  process.exit(1);
}
const infimaCss =
  HEADER +
  `/* Load after Infima and tokens.css. Covers every colour variable of Infima ${INFIMA_VERSION}; the html[data-theme] selectors match Infima's own dark block so these win in both themes. */\n` +
  ":root,\nhtml[data-theme='light'],\nhtml[data-theme='dark'] {\n" +
  infimaLines.join('\n') +
  '\n}\n';

mkdirSync(join(root, 'generated'), { recursive: true });
writeFileSync(join(root, 'tokens.css'), tokensCss);
writeFileSync(join(root, 'generated', 'tailwind-theme.css'), tailwindCss);
writeFileSync(join(root, 'generated', 'infima.css'), infimaCss);
console.log(`tokens.css: ${all.length} tokens (${modal.length} themed); generated/tailwind-theme.css; generated/infima.css (${infimaLines.length} Infima variables)`);

const colorNames = all
  .filter((l) => l.type === 'color')
  .map((l) => ({ name: l.path.slice(1).join('-'), path: l.path.slice(1).join('.'), alpha: l.token.$value.alpha !== undefined, description: l.token.$description ?? '' }));
const tokensJs =
  '/* Generated by scripts/build-tokens.mjs from tokens.json. */\n' +
  `window.PB_TOKENS = ${JSON.stringify({ colors: colorNames, pairs: tokens.$extensions['broker.package.contrastPairs'] })};\n`;
writeFileSync(join(root, 'generated', 'tokens.js'), tokensJs);

const nodeOf = (path) => path.split('.').reduce((n, k) => n[k], tokens.color);
const valueOf = (node, mode) => (mode === 'light' ? node.$value : node.$extensions[MODES_KEY].dark);
const refRows = all
  .filter((l) => l.type === 'color')
  .map((l) => {
    const dark = l.token.$extensions[MODES_KEY].dark;
    return `| \`${l.path.slice(1).join('.')}\` | \`${varName(l.path)}\` | \`${formatOklch(l.token.$value.components, l.token.$value.alpha)}\` ${l.token.$value.hex} | \`${formatOklch(dark.components, dark.alpha)}\` ${dark.hex} | ${l.token.$description ?? ''} |`;
  });
const pairRows = tokens.$extensions['broker.package.contrastPairs'].map((p) => {
  const cells = ['light', 'dark'].map((m) => {
    const r = contrastRatio(serialisedComponents(valueOf(nodeOf(p.fg), m).components), serialisedComponents(valueOf(nodeOf(p.bg), m).components));
    return `${r.toFixed(2)} ${r >= p.min ? 'pass' : 'FAIL'}`;
  });
  return `| \`${p.fg}\` | \`${p.bg}\` | ${p.use} | ${p.min}:1 | ${cells[0]} | ${cells[1]} |`;
});
const referenceMd =
  '<!-- Generated by scripts/build-tokens.mjs from tokens.json. Do not edit. -->\n# Token reference\n\n' +
  '## Colour tokens\n\n| Token | CSS variable | Light | Dark | Role |\n|---|---|---|---|---|\n' + refRows.join('\n') + '\n\n' +
  '## Contrast pairs\n\nWCAG 2.x relative luminance from the serialised OKLCH values. A pair used by `components.css` and not listed here fails `contrast-check.mjs`.\n\n' +
  '| Foreground | Background | Use | Min | Light | Dark |\n|---|---|---|---|---|---|\n' + pairRows.join('\n') + '\n\n' +
  '## Exempt tokens\n\n' + tokens.$extensions['broker.package.contrastExempt'].map((e) => `- \`${e.token}\`: ${e.reason}`).join('\n') + '\n';
writeFileSync(join(root, 'generated', 'reference.md'), referenceMd);
